// ============================================================
// PTS3 Result - Client Script (Visual Inspection)
// Renders: Summary, Step Sweep, Mode, Left/Right/Diff, Artifacts
// Uses final_graph_json, mode_values_json, left_right_diff_summary_json, artifact_paths
// ============================================================

(function () {
  if (document.getElementById("pts3-result-style") == null) {
    var style = document.createElement("style");
    style.id = "pts3-result-style";
    style.textContent = ".pts3-result-section{margin:1rem 0;padding:0.75rem;border:1px solid #d1d8dd;border-radius:4px;}.pts3-result-section h4{margin:0 0 0.5rem 0;font-size:1rem;color:#36414c;}.pts3-result-table{font-size:0.85em;border-collapse:collapse;}.pts3-result-table th,.pts3-result-table td{border:1px solid #d1d8dd;padding:4px 8px;text-align:left;}.pts3-result-table th{background:#f5f7fa;}.pts3-result-artifact{margin:0.25rem 0;font-size:0.9em;}.pts3-result-no-data{color:#8d99a6;font-style:italic;}.pts3-result-pass{color:#27ae60;}.pts3-result-fail{color:#e74c3c;}";
    document.head.appendChild(style);
  }

  function safe_json(str, fallback) {
    if (!str || typeof str !== "string") return fallback || {};
    try {
      var o = JSON.parse(str);
      return o && typeof o === "object" ? o : (fallback || {});
    } catch (e) {
      return fallback || {};
    }
  }

  function escape_html(s) {
    if (s == null || s === undefined) return "";
    var t = String(s);
    return t.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
  }

  function render_summary(frm) {
    var d = frm.doc;
    var html = '<div class="pts3-result-section"><h4>Summary</h4><table class="pts3-result-table"><tbody>';
    html += "<tr><th>PCB Serial No</th><td>" + escape_html(d.pcb_serial_no || "") + "</td></tr>";
    html += "<tr><th>Run ID</th><td>" + escape_html(d.run_id || "") + "</td></tr>";
    html += "<tr><th>Operation</th><td>" + escape_html(d.operation || "") + "</td></tr>";
    html += "<tr><th>Datetime</th><td>" + escape_html(d.datetime || "") + "</td></tr>";
    var pf = (d.pass_fail || "").trim();
    var pfClass = pf === "Pass" ? "pts3-result-pass" : pf === "Fail" ? "pts3-result-fail" : "";
    html += "<tr><th>Pass/Fail</th><td class=\"" + pfClass + "\">" + escape_html(pf || "-") + "</td></tr>";
    html += "<tr><th>Dominant Channel</th><td>" + escape_html(d.dominant_channel || "") + "</td></tr>";
    html += "<tr><th>Max Value</th><td>" + escape_html(d.max_value != null ? d.max_value : "") + "</td></tr>";
    html += "</tbody></table></div>";
    return html;
  }

  function render_step_sweep(frm) {
    var g = safe_json(frm.doc.final_graph_json, null);
    if (!g || g.type !== "sweep") {
      return '<div class="pts3-result-section"><h4>Step Sweep</h4><p class="pts3-result-no-data">No sweep data</p></div>';
    }
    var freqs = g.freqs || [];
    var left = g.left || [];
    var right = g.right || [];
    var diff = g.diff || [];
    var html = '<div class="pts3-result-section"><h4>Step Sweep</h4><table class="pts3-result-table"><thead><tr><th>Freq (Hz)</th><th>Left</th><th>Right</th><th>Diff</th></tr></thead><tbody>';
    for (var i = 0; i < freqs.length; i++) {
      html += "<tr><td>" + escape_html(freqs[i]) + "</td><td>" + escape_html(left[i] != null ? left[i] : "") + "</td><td>" + escape_html(right[i] != null ? right[i] : "") + "</td><td>" + escape_html(diff[i] != null ? diff[i] : "") + "</td></tr>";
    }
    html += "</tbody></table></div>";
    return html;
  }

  function get_mode_value(m, key) {
    if (m[key]) return m[key];
    var lower = key.toLowerCase();
    if (m[lower]) return m[lower];
    return null;
  }

  function render_mode(frm) {
    var m = safe_json(frm.doc.mode_values_json, null);
    if (!m || typeof m !== "object") {
      return '<div class="pts3-result-section"><h4>Mode Results</h4><p class="pts3-result-no-data">No mode data</p></div>';
    }
    var order = ["Mode1", "Mode2", "Mode3", "Mode0"];
    var html = '<div class="pts3-result-section"><h4>Mode Results</h4><table class="pts3-result-table"><thead><tr><th>Mode</th><th>P1</th><th>P2</th><th>Diff</th></tr></thead><tbody>';
    for (var i = 0; i < order.length; i++) {
      var k = order[i];
      var v = get_mode_value(m, k);
      if (v && typeof v === "object") {
        html += "<tr><td>" + escape_html(k) + "</td><td>" + escape_html(v.p1 != null ? v.p1 : "") + "</td><td>" + escape_html(v.p2 != null ? v.p2 : "") + "</td><td>" + escape_html(v.diff != null ? v.diff : "") + "</td></tr>";
      }
    }
    html += "</tbody></table></div>";
    return html;
  }

  function render_lrd_summary(frm) {
    var t = safe_json(frm.doc.left_right_diff_summary_json, null);
    if (!t || typeof t !== "object") {
      return '<div class="pts3-result-section"><h4>Left / Right / Diff Summary</h4><p class="pts3-result-no-data">No data</p></div>';
    }
    var meta = t.metadata || {};
    var left = t.left || {};
    var right = t.right || {};
    var diff = t.diff || {};
    var keys = Object.keys(left).concat(Object.keys(right)).concat(Object.keys(diff));
    keys = keys.filter(function (k, i, a) { return a.indexOf(k) === i; }).sort();
    var html = '<div class="pts3-result-section"><h4>Left / Right / Diff Summary</h4>';
    if (Object.keys(meta).length) {
      html += "<p><strong>Metadata:</strong> " + escape_html(JSON.stringify(meta)) + "</p>";
    }
    html += "<table class=\"pts3-result-table\"><thead><tr><th>Key</th><th>Left</th><th>Right</th><th>Diff</th></tr></thead><tbody>";
    for (var i = 0; i < keys.length; i++) {
      var k = keys[i];
      html += "<tr><td>" + escape_html(k) + "</td><td>" + escape_html(left[k] != null ? left[k] : "") + "</td><td>" + escape_html(right[k] != null ? right[k] : "") + "</td><td>" + escape_html(diff[k] != null ? diff[k] : "") + "</td></tr>";
    }
    html += "</tbody></table></div>";
    return html;
  }

  function render_artifacts(frm) {
    var ap = frm.doc.artifact_paths || "";
    var html = '<div class="pts3-result-section"><h4>Artifacts</h4>';
    var obj = null;
    if (typeof ap === "string" && ap.trim()) {
      try {
        obj = JSON.parse(ap);
      } catch (e) {
        obj = null;
      }
    }
    if (obj && typeof obj === "object") {
      var pc = obj.pc_name || "";
      var excel = obj.excel_path || "";
      var log = obj.log_path || "";
      var plot = obj.plot_path || "";
      html += "<div class=\"pts3-result-artifact\"><strong>PC:</strong> " + escape_html(pc || "(not set)") + "</div>";
      html += "<div class=\"pts3-result-artifact\"><strong>Excel:</strong> " + escape_html(excel || "-") + "</div>";
      html += "<div class=\"pts3-result-artifact\"><strong>Log:</strong> " + escape_html(log || "-") + "</div>";
      html += "<div class=\"pts3-result-artifact\"><strong>Plot:</strong> " + escape_html(plot || "-") + "</div>";
    } else if (ap && typeof ap === "string") {
      html += "<div class=\"pts3-result-artifact\"><strong>Legacy path:</strong> " + escape_html(ap) + "</div>";
    } else {
      html += "<p class=\"pts3-result-no-data\">No artifact paths</p>";
    }
    html += "</div>";
    return html;
  }

  function render_inspection(frm) {
    if (!frm.doc.name) return "";
    var html = render_summary(frm) + render_step_sweep(frm) + render_mode(frm) + render_lrd_summary(frm) + render_artifacts(frm);
    return html;
  }

  frappe.ui.form.on("PTS3 Result", {
    refresh: function (frm) {
      var field = frm.get_field("result_inspection");
      if (field && field.$wrapper) {
        field.$wrapper.html(render_inspection(frm));
      }
    }
  });
})();

