"""
Upsert Client Script:
  Name: PCB Ledger - Visual Timeline Display
  DocType: PCB Ledger

Renders the PCB ledger visual timeline into the HTML field `visual_timeline_html`,
which is already placed in the right column of the Lifecycle Tracking section.
"""

import os
import sys

sys.path.insert(0, os.getcwd())
from AUTO_EXECUTE_FRAPPE_CONSOLE import execute_frappe_command


SCRIPT_JS = """
frappe.ui.form.on('PCB Ledger', {
    refresh(frm) {
        // Use the new dark visual timeline renderer
        render_pcb_visual_timeline_v2(frm);
    },
    after_save(frm) {
        render_pcb_visual_timeline_v2(frm);
    },
});

function render_pcb_visual_timeline(frm) {
    if (!frm || !frm.doc) return;

    const field = frm.fields_dict && frm.fields_dict['visual_timeline_html'];
    if (!field || !field.$wrapper) {
        console.warn('[PCB Timeline] visual_timeline_html field not found');
        return;
    }

    const wrapper = field.$wrapper;
    wrapper.empty();

    const rows = (frm.doc.pcb_ledger_timeline || []).slice();
    if (!rows.length) {
        wrapper.append('<div class=\"text-muted small\">No PCB history yet.</div>');
        return;
    }

    // Sort by event_time ascending (string compare is fine for ISO datetime)
    rows.sort(function (a, b) {
        const ta = a.event_time || '';
        const tb = b.event_time || '';
        if (ta < tb) return -1;
        if (ta > tb) return 1;
        return 0;
    });

    const card = $('<div class=\"pcb-visual-timeline-card\"></div>').appendTo(wrapper);
    $('<div class=\"pcb-visual-timeline-header\">PCB History Timeline</div>').appendTo(card);

    const list = $('<div class=\"pcb-visual-timeline-list\"></div>').appendTo(card);

    rows.forEach(function (row) {
        const rawEventType = row.event_type || '';
        const eventType = frappe.utils.escape_html(rawEventType);
        var dateStr = '';
        try {
            if (row.event_time) {
                dateStr = frappe.datetime.str_to_user(row.event_time);
            }
        } catch (e) {
            dateStr = row.event_time || '';
        }

        const fromLoc = row.from_location || '';
        const toLoc = row.to_location || '';
        let movement = '';
        if (fromLoc || toLoc) {
            movement = fromLoc || '';
            if (toLoc) {
                movement += (movement ? ' \u2192 ' : '') + toLoc; // arrow
            }
        }

        let ref = '';
        if (row.ref_doctype && row.ref_docname) {
            ref = frappe.utils.escape_html(row.ref_doctype + ' - ' + row.ref_docname);
        }

        const rawRemarks = row.remarks || '';
        const remarks = rawRemarks ? frappe.utils.escape_html(rawRemarks) : '';

        // For PTS test events, extract status (Pass/Fail/Pending) and show as a colored chip
        let statusChipHtml = '';
        if (rawEventType === 'PTS1_UPDATED' || rawEventType === 'PTS2_UPDATED' || rawEventType === 'PTS3_UPDATED') {
            let status = null;
            // Remarks look like "PTS1 Result (Attempt N): Fail @ ..."
            const m = /Result[^:]*:\s*([A-Za-z]+)/.exec(rawRemarks || '');
            if (m && m[1]) {
                status = m[1];
            }
            if (status) {
                let cssClass = 'pcb-status-pending';
                const up = String(status).toUpperCase();
                if (up === 'PASS') cssClass = 'pcb-status-pass';
                else if (up === 'FAIL') cssClass = 'pcb-status-fail';
                statusChipHtml =
                    '<span class=\"pcb-status-chip ' +
                    cssClass +
                    '\">' +
                    frappe.utils.escape_html(status) +
                    '</span>';
            }
        } else if (rawEventType === 'MOVED_TO_REJECTED') {
            // Special "RE" chip for any movement to rejected warehouse
            statusChipHtml =
                '<span class=\"pcb-status-chip pcb-status-fail\">RE</span>';
        }

        const metaParts = [];
        if (dateStr) metaParts.push(dateStr);
        if (movement) metaParts.push(movement);
        const metaText = metaParts.join(' \u00b7 ');

        // Build remarks HTML: make PTSx result remarks more prominent, but keep
        // the original muted colour style.
        let remarksHtml = '';
        if (remarks) {
            // Base style uses the same small + text-muted classes as before.
            let remarksClass = 'pcb-visual-timeline-remarks small text-muted';
            if (rawEventType === 'PTS1_UPDATED' || rawEventType === 'PTS2_UPDATED' || rawEventType === 'PTS3_UPDATED') {
                // For PTS events, add an extra class that only increases weight/size,
                // colour still comes from text-muted.
                remarksClass += ' pcb-pts-remarks';
            }
            remarksHtml =
                '    <div class=\"' +
                remarksClass +
                '\">' +
                remarks +
                '</div>';
        }

        const itemHtml =
            '<div class=\"pcb-visual-timeline-item\">' +
            '  <div class=\"pcb-visual-timeline-marker\"></div>' +
            '  <div class=\"pcb-visual-timeline-body\">' +
            '    <div class=\"pcb-visual-timeline-title\">' +
                 eventType +
                (statusChipHtml ? ' ' + statusChipHtml : '') +
            '</div>' +
            (metaText
                ? '    <div class=\"pcb-visual-timeline-meta small text-muted\">' +
                  frappe.utils.escape_html(metaText) +
                  '</div>'
                : '') +
            (ref
                ? '    <div class=\"pcb-visual-timeline-ref small\">' + ref + '</div>'
                : '') +
            remarksHtml +
            '  </div>' +
            '</div>';

        list.append($(itemHtml));
    });

    // Inject CSS once
    if (!window.__pcb_visual_timeline_css) {
        window.__pcb_visual_timeline_css = true;
        const css =
            '<style>' +
            '.pcb-visual-timeline-card { background: #fff; border-radius: 6px; padding: 12px 16px; border: 1px solid #d1d8dd; }' +
            '.pcb-visual-timeline-header { font-weight: 600; margin-bottom: 8px; }' +
            '.pcb-visual-timeline-list { position: relative; margin-left: 4px; }' +
            '.pcb-visual-timeline-item { display: flex; margin-bottom: 10px; position: relative; }' +
            '.pcb-visual-timeline-marker { width: 10px; margin-right: 8px; position: relative; }' +
            '.pcb-visual-timeline-marker::before { content: \"\"; position: absolute; left: 3px; top: 3px; width: 6px; height: 6px; border-radius: 50%; background: #5e64ff; }' +
            '.pcb-visual-timeline-marker::after { content: \"\"; position: absolute; left: 6px; top: 10px; width: 2px; bottom: -10px; background: #d1d8dd; }' +
            '.pcb-visual-timeline-item:last-child .pcb-visual-timeline-marker::after { display: none; }' +
            '.pcb-visual-timeline-body { flex: 1; }' +
            '.pcb-visual-timeline-title { font-weight: 500; display: flex; align-items: center; gap: 6px; }' +
            '.pcb-visual-timeline-ref { margin-top: 2px; }' +
            '.pcb-visual-timeline-remarks { margin-top: 2px; }' +
            '.pcb-pts-remarks { margin-top: 4px; font-weight: 600; }' +
            '.pcb-status-chip { display: inline-block; padding: 1px 6px; border-radius: 999px; font-size: 10px; }' +
            '.pcb-status-pass { background: #d4edda; color: #155724; }' +
            '.pcb-status-fail { background: #f8d7da; color: #721c24; }' +
            '.pcb-status-pending { background: #fff3cd; color: #856404; }' +
            '</style>';
        $(document.head).append(css);
    }
}

