/**
 * PCB Ledger - Visual Timeline Display Client Script
 * 
 * Displays timeline in TWO formats:
 * 1. Vertical Timeline view with markers and connecting lines
 * 2. Table Format view with sortable columns
 * 
 * Both use same data from pcb_ledger_timeline child table
 */

frappe.ui.form.on('PCB Ledger', {
    refresh: function(frm) {
        // Add toggle button for view switching (do NOT clear standard actions)
        frm.add_custom_button(getToggleLabel(frm), function() {
            toggleTimelineView(frm);
        }, __('View'));

        // Render on refresh (show empty state if no entries yet)
        renderTimeline(frm, getCurrentView(frm));
    },

    pcb_ledger_timeline_on_change: function(frm) {
        // Re-render timeline when timeline entries change
        renderTimeline(frm, getCurrentView(frm));
    }
});

// Store current view in form
function getCurrentView(frm) {
    if (!frm._timeline_view) {
        frm._timeline_view = 'vertical'; // Default
    }
    return frm._timeline_view;
}

function setCurrentView(frm, view) {
    frm._timeline_view = view;
}

function getToggleLabel(frm) {
    const currentView = getCurrentView(frm);
    return currentView === 'vertical' ? __('Switch to Table View') : __('Switch to Timeline View');
}

// Toggle between views
function toggleTimelineView(frm) {
    const currentView = getCurrentView(frm);
    const newView = currentView === 'vertical' ? 'table' : 'vertical';
    setCurrentView(frm, newView);
    renderTimeline(frm, newView);
}

function getSortState(frm) {
    if (!frm._timeline_sort) {
        frm._timeline_sort = { field: 'event_time', asc: true };
    }
    return frm._timeline_sort;
}

function toggleSort(frm, field) {
    const s = getSortState(frm);
    if (s.field === field) {
        s.asc = !s.asc;
    } else {
        s.field = field;
        s.asc = true;
    }
    frm._timeline_sort = s;
}

// Render timeline in specified format
function renderTimeline(frm, viewType) {
    console.log('[PCB Ledger Timeline] Rendering', viewType, 'view');

    // Get timeline data
    const timelineData = frm.doc.pcb_ledger_timeline || [];

    if (timelineData.length === 0) {
        // Show empty state in the HTML field if present
        const htmlField = frm.fields_dict.visual_timeline_html;
        if (htmlField && htmlField.wrapper) {
            $(htmlField.wrapper).html(
                '<div style="padding:12px; color:#74808b;">No timeline entries yet.</div>'
            );
        }
        return;
    }

    let sortedData = [...timelineData];
    if (viewType === 'vertical') {
        // Always chronological in vertical view
        sortedData.sort((a, b) => (new Date(a.event_time || 0)) - (new Date(b.event_time || 0)));
    } else {
        const s = getSortState(frm);
        sortedData.sort((a, b) => {
            const av = a[s.field];
            const bv = b[s.field];
            // date fields
            if (s.field === 'event_time') {
                const da = new Date(av || 0);
                const db = new Date(bv || 0);
                return s.asc ? (da - db) : (db - da);
            }
            // string-ish fields
            const as = (av || '').toString().toLowerCase();
            const bs = (bv || '').toString().toLowerCase();
            if (as < bs) return s.asc ? -1 : 1;
            if (as > bs) return s.asc ? 1 : -1;
            return 0;
        });
    }

    // Find or create timeline container
    let container = $(frm.fields_dict.pcb_ledger_timeline.wrapper).closest('.form-section');
    let timelineContainer = container.find('.pcb-timeline-display');

    if (timelineContainer.length === 0) {
        // Create container
        timelineContainer = $('<div class="pcb-timeline-display" style="margin-top: 20px; padding: 20px; border: 1px solid #d1d8dd; border-radius: 4px; background: #fff;"></div>');
        container.append(timelineContainer);
    }

    // Clear and render based on view type
    timelineContainer.empty();

    if (viewType === 'vertical') {
        renderVerticalTimeline(timelineContainer, sortedData);
    } else {
        renderTableView(frm, timelineContainer, sortedData);
    }
}

// Render Vertical Timeline View
function renderVerticalTimeline(container, data) {
    console.log('[PCB Ledger Timeline] Rendering vertical timeline with', data.length, 'entries');

    const timelineHTML = $('<div class="pcb-vertical-timeline"></div>');

    data.forEach((entry, index) => {
        const entryDiv = $('<div class="timeline-entry" style="position: relative; padding-left: 40px; margin-bottom: 30px;"></div>');

        // Event marker
        const markerColor = getMarkerColor(entry.event_type);
        const marker = $(`
            <div class="timeline-marker" style="
                position: absolute;
                left: 0;
                top: 0;
                width: 16px;
                height: 16px;
                border-radius: 50%;
                background: ${markerColor};
                border: 2px solid #fff;
                box-shadow: 0 0 0 2px ${markerColor};
                z-index: 2;
            "></div>
        `);
        entryDiv.append(marker);

        // Connecting line (except last)
        if (index < data.length - 1) {
            const line = $(`
                <div class="timeline-line" style="
                    position: absolute;
                    left: 7px;
                    top: 16px;
                    width: 2px;
                    height: calc(100% + 14px);
                    background: #d1d8dd;
                    z-index: 1;
                "></div>
            `);
            entryDiv.append(line);
        }

        // Event time
        const timeDiv = $('<div class="timeline-time" style="font-weight: 600; color: #36414c; margin-bottom: 5px;"></div>');
        timeDiv.text(formatDateTime(entry.event_time));
        entryDiv.append(timeDiv);

        // Event type
        const eventDiv = $('<div class="timeline-event" style="font-size: 14px; font-weight: 600; color: #36414c; margin-bottom: 8px;"></div>');
        eventDiv.text(entry.event_type || 'Unknown Event');
        entryDiv.append(eventDiv);

        // Event details
        const detailsDiv = $('<div class="timeline-details" style="font-size: 12px; color: #74808b; line-height: 1.6;"></div>');

        if (entry.from_location || entry.to_location) {
            detailsDiv.append($('<div></div>').text(`From: ${entry.from_location || '-'} → To: ${entry.to_location || '-'}`));
        }

        if (entry.ref_docname) {
            detailsDiv.append($('<div></div>').text(`Reference: ${entry.ref_doctype} - ${entry.ref_docname}`));
        }

        if (entry.actor_user) {
            detailsDiv.append($('<div></div>').text(`User: ${entry.actor_user}`));
        }

        if (entry.remarks) {
            detailsDiv.append($('<div style="margin-top: 5px; font-style: italic;"></div>').text(`Remarks: ${entry.remarks}`));
        }

        // Click to show snapshot
        entryDiv.css('cursor', 'pointer');
        entryDiv.on('click', function() {
            showSnapshotModal(entry);
        });

        entryDiv.append(detailsDiv);
        timelineHTML.append(entryDiv);
    });

    container.append(timelineHTML);
}

// Render Table View
function renderTableView(frm, container, data) {
    console.log('[PCB Ledger Timeline] Rendering table view with', data.length, 'entries');
    const sortState = getSortState(frm);
    const sortArrow = (field) => {
        if (sortState.field !== field) return '';
        return sortState.asc ? ' ▲' : ' ▼';
    };

    const tableHTML = $(`
        <table class="pcb-timeline-table table table-bordered" style="width: 100%; margin-top: 10px;">
            <thead>
                <tr style="background: #f5f7fa;">
                    <th class="pcb-sort" data-field="event_time" style="padding: 8px; cursor: pointer;">Date/Time${sortArrow('event_time')}</th>
                    <th class="pcb-sort" data-field="event_type" style="padding: 8px; cursor: pointer;">Event${sortArrow('event_type')}</th>
                    <th style="padding: 8px;">Status</th>
                    <th class="pcb-sort" data-field="from_location" style="padding: 8px; cursor: pointer;">From${sortArrow('from_location')}</th>
                    <th class="pcb-sort" data-field="to_location" style="padding: 8px; cursor: pointer;">To${sortArrow('to_location')}</th>
                    <th class="pcb-sort" data-field="actor_user" style="padding: 8px; cursor: pointer;">User${sortArrow('actor_user')}</th>
                    <th class="pcb-sort" data-field="ref_docname" style="padding: 8px; cursor: pointer;">Reference${sortArrow('ref_docname')}</th>
                    <th style="padding: 8px;">Actions</th>
                </tr>
            </thead>
            <tbody></tbody>
        </table>
    `);

    // Hook sorting (no inline JS)
    tableHTML.find('th.pcb-sort').on('click', function() {
        const field = $(this).data('field');
        toggleSort(frm, field);
        renderTimeline(frm, 'table');
    });

    const tbody = tableHTML.find('tbody');

    data.forEach((entry) => {
        const row = $('<tr style="cursor: pointer;"></tr>');

        // Date/Time
        row.append($('<td></td>').text(formatDateTime(entry.event_time)));

        // Event Type
        row.append($('<td></td>').text(entry.event_type || '-'));

        // Status (from stage_after_event)
        const statusBadge = getStatusBadge(entry.stage_after_event);
        row.append($('<td></td>').html(statusBadge));

        // From Location
        row.append($('<td></td>').text(entry.from_location || '-'));

        // To Location
        row.append($('<td></td>').text(entry.to_location || '-'));

        // User
        row.append($('<td></td>').text(entry.actor_user || '-'));

        // Reference
        const refText = entry.ref_docname ? `${entry.ref_doctype} - ${entry.ref_docname}` : '-';
        row.append($('<td></td>').text(refText));

        // Actions
        const actionsCell = $('<td></td>');
        const viewBtn = $('<button class="btn btn-sm btn-default">View Snapshot</button>');
        viewBtn.on('click', function(e) {
            e.stopPropagation();
            showSnapshotModal(entry);
        });
        actionsCell.append(viewBtn);
        row.append(actionsCell);

        // Click row to show snapshot
        row.on('click', function() {
            showSnapshotModal(entry);
        });

        tbody.append(row);
    });

    container.append(tableHTML);
}

// Helper functions
function getMarkerColor(eventType) {
    const colorMap = {
        'RECEIVED_IN_OFFICE': '#4285f4', // Blue
        'MOVED_TO_PTS_TESTING': '#9c27b0', // Purple
        'MOVED_TO_STORES': '#4caf50', // Green
        'MOVED_TO_ASSEMBLY': '#4caf50', // Green
        'MOVED_TO_REJECTED': '#f44336', // Red
        'PTS1_UPDATED': '#9c27b0', // Purple
        'PTS2_UPDATED': '#9c27b0', // Purple
        'PTS3_UPDATED': '#9c27b0', // Purple
        'IQC_SUBMITTED': '#9c27b0', // Purple
        'STATUS_COMPUTED': '#ff9800' // Orange
    };
    return colorMap[eventType] || '#757575'; // Default gray
}

function getStatusBadge(stage) {
    const badgeMap = {
        'INBOUND': '<span class="badge" style="background: #4285f4;">INBOUND</span>',
        'INCOMING_QC': '<span class="badge" style="background: #9c27b0;">INCOMING_QC</span>',
        'PTS_TESTING': '<span class="badge" style="background: #9c27b0;">PTS_TESTING</span>',
        'STORES': '<span class="badge" style="background: #4caf50;">STORES</span>',
        'ASSEMBLY': '<span class="badge" style="background: #4caf50;">ASSEMBLY</span>',
        'REJECTED': '<span class="badge" style="background: #f44336;">REJECTED</span>',
        'SCRAP': '<span class="badge" style="background: #757575;">SCRAP</span>'
    };
    return badgeMap[stage] || '<span class="badge">-</span>';
}

function formatDateTime(datetimeStr) {
    if (!datetimeStr) return '-';
    try {
        const dt = new Date(datetimeStr);
        return dt.toLocaleString('en-US', {
            year: 'numeric',
            month: '2-digit',
            day: '2-digit',
            hour: '2-digit',
            minute: '2-digit'
        });
    } catch (e) {
        return datetimeStr;
    }
}

function showSnapshotModal(entry) {
    console.log('[PCB Ledger Timeline] Showing snapshot for entry:', entry);

    // Parse snapshots
    let masterSnapshot = {};
    let extraPayload = {};
    let masterSnapshotRaw = entry.master_snapshot_json || '';
    let extraPayloadRaw = entry.extra_payload_json || '';

    try {
        if (entry.master_snapshot_json) {
            masterSnapshot = JSON.parse(entry.master_snapshot_json);
        }
    } catch (e) {
        console.error('[PCB Ledger Timeline] Error parsing master snapshot:', e);
    }

    try {
        if (entry.extra_payload_json) {
            extraPayload = JSON.parse(entry.extra_payload_json);
        }
    } catch (e) {
        console.error('[PCB Ledger Timeline] Error parsing extra payload:', e);
    }

    const masterDisplay = Object.keys(masterSnapshot || {}).length ? JSON.stringify(masterSnapshot, null, 2) : (masterSnapshotRaw || '-');
    const payloadDisplay = Object.keys(extraPayload || {}).length ? JSON.stringify(extraPayload, null, 2) : (extraPayloadRaw || '-');

    // Create modal
    const d = new frappe.ui.Dialog({
        title: `Timeline Entry: ${entry.event_type}`,
        fields: [
            {
                fieldtype: 'HTML',
                options: `
                    <div style="max-height: 600px; overflow-y: auto;">
                        <h4>Master Snapshot</h4>
                        <pre style="background: #f5f7fa; padding: 15px; border-radius: 4px; font-size: 12px; white-space: pre-wrap;">${frappe.utils.escape_html(masterDisplay)}</pre>
                        <h4 style="margin-top: 20px;">Event Details</h4>
                        <pre style="background: #f5f7fa; padding: 15px; border-radius: 4px; font-size: 12px; white-space: pre-wrap;">${frappe.utils.escape_html(payloadDisplay)}</pre>
                    </div>
                `
            }
        ],
        primary_action_label: 'Close',
        primary_action: function() {
            d.hide();
        }
    });

    d.show();
}

// No global sortTable needed; handled via click listeners in renderTableView
